#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int num; char name[32]; struct Node *next; } Node;
Node *read_list(int n) {
    Node *head = NULL, **tail = &head;
    for (int i = 0; i < n; i++) {
        Node *node = malloc(sizeof(*node));
        if (!node) exit(1);
        scanf("%d%31s", &node->num, node->name);
        node->next = NULL; *tail = node; tail = &node->next;
    }
    return head;
}
void destroy(Node *head) {
    while (head) { Node *next = head->next; free(head); head = next; }
}

int main(void) {
    int n, m;
    scanf("%d", &n); Node *a = read_list(n);
    scanf("%d", &m); Node *b = read_list(m);
    Node **link = &a;
    while (*link) {
        int found = 0;
        for (Node *p = b; p; p = p->next) if (p->num == (*link)->num) found = 1;
        if (found) { Node *old = *link; *link = old->next; free(old); }
        else link = &(*link)->next;
    }
    if (!a) puts("EMPTY");
    for (Node *p = a; p; p = p->next) printf("%d %s\n", p->num, p->name);
    destroy(a); destroy(b);
    return 0;
}
